// logger, usage: log(this, "");
const log = (global.get('logger') || (() => {}));

// 1.  Input
const minDeltaCents = parseInt(RED.util.getMessageProperty(msg, "dynamic.min_delta_cents")) || 0;
// Per-day caps on the number of LOW / HIGH marks, expressed in hours.
// 0 (or missing/invalid/negative) means no limit.
const cheapestHrs = parseFloat(RED.util.getMessageProperty(msg, "dynamic.cheapest_hrs")) || 0;
const expensiveHrs = parseFloat(RED.util.getMessageProperty(msg, "dynamic.expensive_hrs")) || 0;
const dataAll = RED.util.getMessageProperty(msg, "dynamic.data_all");

const STRATEGY = {
    HIGH: RED.util.getMessageProperty(msg, "dynamic.strategy_expensive") || "Self-consumption",
    LOW: RED.util.getMessageProperty(msg, "dynamic.strategy_cheapest") || "Charge",
    NEUTRAL: RED.util.getMessageProperty(msg, "dynamic.strategy_default") || "Charge PV",
};

if (!dataAll || !Array.isArray(dataAll.list) || dataAll.list.length === 0) {
    // No prices (HBC+ v1.0): publish the empty set with status 'no_data', so the Price
    // intervals chart shows 'No Data Available' and HA raises binary_sensor.hbc_price_data_missing.
    // Without prices there is no basis for 'cheap' or 'expensive', so Dynamic falls back to the
    // baseline strategy instead of staying on the last one (which could be grid charging).
    log(this, `Price list missing or empty - falling back to the baseline strategy **${STRATEGY.NEUTRAL}**`, "warn");
    node.status({ fill: "red", shape: "ring", text: `No price data -> ${STRATEGY.NEUTRAL}` });
    RED.util.setMessageProperty(msg, "dynamic.data_all", { list: [], list_marked: [], average: 0, mark_now: 'No data', start: 'Unknown', datapoints_per_hour: 0, net_spread_avg: 0, gross_spread_avg: 0, status: 'no_data' }, true);
    RED.util.setMessageProperty(msg, "dynamic.strategy", STRATEGY.NEUTRAL);
    flow.set("dynamic_strategy", STRATEGY.NEUTRAL);
    return msg;
}
const priceStatus = msg.dynamic.stale ? 'stale' : 'ok';

// 2.  Build interval timestamps
// Each datapoint covers (hours / datapoints) hours.
const prices = dataAll.list; // cents/kWh — already converted by "Convert price" node
const n = prices.length;
// HBC+ v1.2: the sell price per interval (Price split guarantees one; sell = buy for sources
// without a separate export price). The HIGH side of a pair is valued at the sell price only
// when the expensive strategy is Sell; otherwise at the buy price it avoids.
const sells = (Array.isArray(dataAll.sell) && dataAll.sell.length === n) ? dataAll.sell : prices;
const highVals = STRATEGY.HIGH === 'Sell' ? sells : prices;
const sellSplit = highVals !== prices && sells.some((v, i) => v !== prices[i]);
const startTime = new Date(dataAll.start);
const intervalMs = (dataAll.hours / dataAll.datapoints) * 3_600_000;

// 3.  Mark intervals: pair extremes inward — independently per calendar day
//
// Pairing runs separately within each local calendar day, so today's marks
// don't shift when tomorrow's prices arrive. Pair detection is one-to-one
// (each candidate HIGH is matched against one candidate LOW), but the
// per-day cheapest_hrs / expensive_hrs caps may suppress one side of a
// detected pair — so the final marks can be asymmetric (e.g. 2 LOW + 1 HIGH
// in a day if expensive_hrs caps HIGH at 1). The minDelta threshold
// accounts for round-trip efficiency and other losses, so a pair is only
// considered viable when its spread covers the loss.
//
// Method (Extreme-Pair Matching, O(n log n)):
//   1. Sort intervals by price, keep original time-index for re-mapping.
//   2. Two pointers walk inward from the extremes — `lo` from the cheapest
//      unmatched, `hi` from the most-expensive unmatched.
//   3. If the spread between them clears minDelta: mark them, advance both.
//   4. If it does not clear minDelta: the cheapest unmatched LOW paired
//      with the most-expensive unmatched HIGH yields the largest spread
//      still achievable. If even that fails, no remaining pair can satisfy
//      the threshold, so we stop.
//
// This algorithm prefers to mark the truly extreme
// hours (highest-priced as HIGH, lowest-priced as LOW). On well-behaved
// daily curves this produces the same number of pairs as 
// other algorithm variants; but in tight cases it can produce one or two fewer
// pairs. Why choose this version? It marks the price peaks/troughs the user
// would intuitively expect, which is good for user confidence and acceptance of the strategy. It is also efficient and straightforward to implement, without needing complex data structures or backtracking. 
// The main goal is to identify a set of HIGH and LOW intervals that are economically justified by their price spread, while keeping the logic transparent and explainable to the user.

// Note:
// It is up to the user to set minDelta appropriately for their system's efficiency and other costs, to ensure that marked cycles are truly beneficial.
// Also the user can pick strategies that reflect their preferences for what to do during LOW and HIGH intervals, e.g. prioritising self-consumption during HIGH intervals, or selling back to the grid if allowed and profitable.
// This makes optimisation flexible and user-configurable, while still being based on a clear economic rationale.
// However, the algorithm does not attempt to find the optimal global pairing (which would be more complex), but rather a good local pairing that is computationally efficient and easy to understand.

/**
 * @typedef {{ start: Date, end: Date, price: number, mark: 'high'|'low'|null, is_now: boolean }} Interval
 * @type {Interval[]}
 */
const intervals = new Array(n);
for (let i = 0; i < n; i++) {
    const iStart = new Date(startTime.getTime() + i * intervalMs);
    const iEnd = new Date(iStart.getTime() + intervalMs);
    // neg (HBC+ v1.2): 'import' = paid to take power, 'export' = feeding in costs money.
    const neg = prices[i] < 0 ? 'import' : (sells[i] < 0 ? 'export' : null);
    intervals[i] = { start: iStart, end: iEnd, price: prices[i], sell: sells[i], neg, mark: null, is_now: false };
}

// Group interval indices by local calendar day (key = Y-M-D in local TZ).
const dayBuckets = new Map();
for (let i = 0; i < n; i++) {
    const d = intervals[i].start;
    const key = `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;
    let bucket = dayBuckets.get(key);
    if (!bucket) { bucket = []; dayBuckets.set(key, bucket); }
    bucket.push(i);
}

// Convert per-day hour caps to per-day interval counts.
// intervalsPerHour = datapoints / hours (e.g. 4 for 15-min intervals).
// 0 hrs => Infinity (no cap). Negatives are treated as 0 (no cap).
const intervalsPerHour = dataAll.datapoints / dataAll.hours;
const maxLowPerDay = cheapestHrs > 0 ? Math.round(cheapestHrs * intervalsPerHour) : Infinity;
const maxHighPerDay = expensiveHrs > 0 ? Math.round(expensiveHrs * intervalsPerHour) : Infinity;

// Per dag de markeringen zetten.
let fullPairCount = 0;   // pairs where BOTH sides were marked (a complete cycle)
let lowMarkCount = 0;    // total LOW marks across all days
let highMarkCount = 0;   // total HIGH marks across all days
for (const dayIndices of dayBuckets.values()) {
    if (sellSplit) {
        // HBC+ v1.2, Sell with a separate sell price: lows ranked by buy price, highs by sell
        // price, each interval used once. Same extreme-pair idea and the same per-day caps;
        // stops when the best remaining pair no longer clears the minimum spread.
        const lows = [...dayIndices].sort((a, b) => prices[a] - prices[b]);
        const highs = [...dayIndices].sort((a, b) => highVals[b] - highVals[a]);
        const used = new Set();
        let li = 0, hj = 0, lowMarkedToday = 0, highMarkedToday = 0;
        while (true) {
            while (li < lows.length && used.has(lows[li])) li++;
            while (hj < highs.length && used.has(highs[hj])) hj++;
            if (li >= lows.length || hj >= highs.length) break;
            const loIdx = lows[li];
            const hiIdx = highs[hj];
            if (loIdx === hiIdx) { hj++; continue; }   // one interval cannot be both
            if (highVals[hiIdx] - prices[loIdx] < minDeltaCents) break;
            const markLow = lowMarkedToday < maxLowPerDay;
            const markHigh = highMarkedToday < maxHighPerDay;
            if (!markLow && !markHigh) break;
            if (markLow) { intervals[loIdx].mark = 'low'; lowMarkedToday++; lowMarkCount++; }
            if (markHigh) { intervals[hiIdx].mark = 'high'; highMarkedToday++; highMarkCount++; }
            if (markLow && markHigh) fullPairCount++;
            used.add(loIdx); used.add(hiIdx);
            li++; hj++;
        }
        continue;
    }
    // This day's indices sorted ascending by price (stable on ties).
    const sortedIdx = [...dayIndices].sort((a, b) => prices[a] - prices[b]);
    let lo = 0;
    let hi = sortedIdx.length - 1;
    let lowMarkedToday = 0;
    let highMarkedToday = 0;
    while (lo < hi) {
        const loIdx = sortedIdx[lo];
        const hiIdx = sortedIdx[hi];
        if (prices[hiIdx] - prices[loIdx] >= minDeltaCents) {
            const markLow = lowMarkedToday < maxLowPerDay;
            const markHigh = highMarkedToday < maxHighPerDay;
            // Both caps reached on this day — no more useful work here.
            if (!markLow && !markHigh) break;
            if (markLow) {
                intervals[loIdx].mark = 'low';
                lowMarkedToday++;
                lowMarkCount++;
            }
            if (markHigh) {
                intervals[hiIdx].mark = 'high';
                highMarkedToday++;
                highMarkCount++;
            }
            if (markLow && markHigh) fullPairCount++;
            lo++; hi--;
        } else {
            // sortedIdx[lo] is the cheapest unmatched within this day,
            // sortedIdx[hi] the most-expensive. Their spread is the largest
            // still possible today — if it falls below minDelta, no further
            // pair on this day can satisfy the threshold.
            break;
        }
    }
}

// 4.  Determine current strategy
const now = new Date();
const currentInterval = intervals.find(iv => now >= iv.start && now < iv.end);
if (currentInterval) currentInterval.is_now = true;
const currentMark = currentInterval ? currentInterval.mark : null;

const strategy =
    currentMark === 'high' ? STRATEGY.HIGH :
        currentMark === 'low' ? STRATEGY.LOW :
            STRATEGY.NEUTRAL;

const strategyMark = 
    currentMark === 'high' ? 'Expensive' :
        currentMark === 'low' ? 'Cheap' :
            'Regular';


// 5.  Store results
RED.util.setMessageProperty(msg,"dynamic.data_all.list_marked",intervals,true);
RED.util.setMessageProperty(msg, "dynamic.data_all.mark_now", strategyMark, true);
RED.util.setMessageProperty(msg, "dynamic.data_all.status", priceStatus, true); // ok | stale (fetch failed, last valid prices in use)
RED.util.setMessageProperty(msg,"dynamic.strategy",strategy);
flow.set("dynamic_strategy", strategy); // this is the strategy executed when dynamic strategy is active, see the 'Execute' section of this flow.

// 6.  Explain
// Extract and sort marked intervals to pair them correctly for profit analysis
const lowPrices = intervals
    .filter(iv => iv.mark === 'low')
    .map(iv => iv.price)
    .sort((a, b) => a - b); // Cheapest first
const highPrices = intervals
    .filter(iv => iv.mark === 'high')
    .map(iv => (sellSplit ? iv.sell : iv.price))
    .sort((a, b) => b - a); // Most expensive first

// Only calculate spread over actual completed cycles (pairs)
let grossSpread = 0;
for (let i = 0; i < fullPairCount; i++) {
    grossSpread += (highPrices[i] - lowPrices[i]);
}
const netSpread = grossSpread - (fullPairCount * minDeltaCents);
const markedCount = lowMarkCount + highMarkCount;

// 6a. Average spread per full cycle (pair) today
const avgGrossSpread = fullPairCount > 0 ? Math.round(grossSpread / fullPairCount) : 0;
const avgNetSpread = fullPairCount > 0 ? Math.round(netSpread / fullPairCount) : 0;
RED.util.setMessageProperty(msg, "dynamic.data_all.gross_spread_avg", avgGrossSpread, true);
RED.util.setMessageProperty(msg, "dynamic.data_all.net_spread_avg", avgNetSpread, true);

// 6b.
node.status({
    fill: priceStatus === 'stale' ? "yellow" : "blue", shape: "dot",
    text: `${priceStatus === 'stale' ? '(last prices) ' : ''}${strategy} | ${fullPairCount} cycle${fullPairCount === 1 ? '' : 's'} | net Σ${avgNetSpread}¢`
});
log(this, `Strategy: **${strategy}** | cycles=${fullPairCount} low=${lowMarkCount} high=${highMarkCount} unmarked=${n - markedCount} | gross=${grossSpread}¢ net=${avgNetSpread}¢ minDelta=${minDeltaCents}¢ caps=L${cheapestHrs}h/H${expensiveHrs}h`);

return msg;

// logger, usage: log(this, "");
const log = (global.get('logger') || (() => {}));

/*    From cheapes-energy-hours macro
      See: https://github.com/TheFes/cheapest-energy-hours/blob/main/documentation/1-source_data.md#data-provider-settings

      - None (default selection)
      - Zonneplan
      - Amber Electric
      - EasyEnergy, EnergyZero (core)
      - ENTSO-E
      - Frank Energie
      - GE-Spot
      - Grid Clock feed (HBC+ v1.2, fetched directly, not through the macro)
      - Tibber, Nordpool (core)
      - Tibber (custom)
      - Nordpool (custom)
      - PVPC (Spain)
      - Octopus Energy
      - Omie
*/

switch (msg.dynamic.data_source) {
      case "None":
            // Handle the 'None' case (e.g., no supplier selected or data is unavailable)
            log(this,"No data source selected.");
            // Add config here...
            break;

      case "Zonneplan":
            // Code for Zonneplan (a Dutch energy supplier)
            // when using: https://github.com/fsaris/home-assistant-zonneplan-one
            log(this,"Processing Zonneplan data.");
            // Add config here...
            // Zonneplan publishes quarter-hourly tariffs on their own entity, with the price
            // nested in price_tax_included.amount. A nested value can not be reached with
            // value_key (the macro reads item[value_key]), so the list is reshaped here and
            // handed to the macro through price_data. Needs Cheapest Energy Hours >= v6.0.0.
            // Falls back to the legacy hourly attributes when the quarter-hourly entity is
            // not available. Both shapes use the same 1e-7 scale, so value_conversion holds
            // for either of them.
            msg.dynamic.template_prefix =
`{%- set zp = namespace(list=[]) -%}
{%- set q = state_attr('sensor.zonneplan_current_quarter_hourly_electricity_tariff', 'forecast') -%}
{%- for i in q or [] -%}
{%- set zp.list = zp.list + [{'start': i['start_date'], 'price': i['price_tax_included']['amount']}] -%}
{%- endfor -%}
{%- if not q -%}
{%- for i in state_attr('sensor.zonneplan_current_electricity_tariff', 'forecast') or [] -%}
{%- set zp.list = zp.list + [{'start': i['datetime'], 'price': i['electricity_price']}] -%}
{%- endfor -%}
{%- endif -%}`;
            msg.dynamic.price_data = 'zp.list';
            msg.dynamic.time_key = 'start';
            msg.dynamic.value_key = 'price';
            msg.dynamic.value_conversion = 10000000; // whole currency / kWh
            break;

      case "Amber Electric":
            // Code for Amber Electric (Australian energy retailer)
            log(this,"Processing Amber Electric data.");
            // Add config here...
            msg.dynamic.attr_all='forecasts'; 
            msg.dynamic.time_key='start_time'; 
            msg.dynamic.value_key='per_kwh';
            break;

      case "EasyEnergy, EnergyZero (core)":
            // Code for EasyEnergy and EnergyZero (core/default implementation)
            log(this,"Processing EasyEnergy/EnergyZero core data.");
            // Add config here...
            break;

      case "ENTSO-E":
            // Code for ENTSO-E (European Network of Transmission System Operators for Electricity)
            log(this,"Processing ENTSO-E data.");
            // Add config here...
            msg.dynamic.attr_today='prices_today'; 
            msg.dynamic.attr_tomorrow='prices_tomorrow'; 
            msg.dynamic.time_key='time';
            msg.dynamic.value_key='price';
            break;

      case "Frank Energie":
            // Code for Frank Energie (Dutch energy supplier)
            log(this,"Processing Frank Energie data.");
            // Add config here...
            msg.dynamic.sensor = 'sensor.frank_energie_prijzen_gemiddelde_elektriciteitsprijs_alle_uren_all_in'; // when using: https://github.com/HiDiHo01/home-assistant-frank_energie
            msg.dynamic.attr_all = 'prices'; 
            msg.dynamic.time_key = 'from'; 
            msg.dynamic.value_key = 'price';
            break;

      case "GE-Spot":
            // Code for GE-Spot (Global Electric Spot price)
            log(this,"Processing GE-Spot data.");
            // Add config here...
            msg.dynamic.attr_today = 'today_hourly_prices'; // using the hourly version. today_interval_prices is per 15 mins
            msg.dynamic.attr_tomorrow = 'tomorrow_hourly_prices'; // using the hourly version
            msg.dynamic.time_key = 'time'; 
            msg.dynamic.value_key = 'value';
            break;

      case "Nordpool (core)":
            // Code for Nordpool (core/default implementation)
            log(this, "Processing Nordpool core data.");
            // Add config here...
            msg.dynamic.sensor = 'sensor.nordpool_ceh_prices';
            msg.dynamic.attr_today = 'today';
            msg.dynamic.attr_tomorrow = 'tomorrow';
            msg.dynamic.time_key = 'start';
            msg.dynamic.value_key = 'value';
            msg.dynamic.datetime_in_data = true; // datetime is in the data
            break;

      case "Tibber (core)":
            // Code for Tibber (core/default implementation)
            log(this,"Processing Tibber core data.");
            // Add config here...
            msg.dynamic.sensor = 'sensor.tibber_ceh_prices';
            msg.dynamic.attr_today = 'today';
            msg.dynamic.attr_tomorrow = 'tomorrow';
            msg.dynamic.time_key = 'start';
            msg.dynamic.value_key = 'value';
            msg.dynamic.datetime_in_data = true; // datetime is in the data
            break;

      case "Tibber (custom)":
            // Code for a custom Tibber setup/configuration
            log(this,"Processing Tibber custom data.");
            // Add config here...
            msg.dynamic.attr_today = 'today';
            msg.dynamic.attr_tomorrow = 'tomorrow';
            msg.dynamic.datetime_in_data = false;
            break;

      case "Nordpool (custom)":
            // Code for a custom Nordpool setup/configuration
            log(this,"Processing Nordpool custom data.");
            // Add config here...
            break;

      case "PVPC (Spain)":
            // Code for PVPC (Voluntary Price for Small Consumers in Spain)
            log(this,"Processing Spanish PVPC data.");
            // Add config here...
            break;

      case "Octopus Energy":
            // Code for Octopus Energy (UK/international energy supplier)
            log(this,"Processing Octopus Energy data.");
            // Add config here...
            msg.dynamic.attr_all = 'rates'; 
            msg.dynamic.value_key = 'value_incl_vat';
            break;

      case "Omie":
            // Code for Omie (Iberian Energy Market Operator)
            log(this,"Processing Omie data.");
            // Add config here...
            break;

      case "Grid Clock feed":
            // HBC+ v1.2: the public Grid Clock feed (cdn.gridclock.eu/v1/hbc/{zone}/{slug}/
            // latest.json) with all-in buy and sell prices per slot for the chosen supplier.
            // No token, no registration. Not through the Cheapest Energy Hours macro: the
            // feed is fetched directly (output 2) and is already in ct/kWh.
            log(this, "Processing Grid Clock feed.");
            msg.dynamic.gc_feed = true;
            break;

      default:
            // Code to execute if the supplier does not match any of the above cases
            node.warn(`Unknown supplier: ${msg.dynamic.data_source}. Using default logic.`);
            log(this,`Unknown supplier: ${msg.dynamic.data_source}. Using default logic.`);
            // Add default error handling...
}

// --- Price sensor (HBC+ v1.0) ------------------------------------------------------------
// input_text.house_battery_strategy_dynamic_price_sensor pins the price sensor for the
// macro. Without it, sources that name no sensor above (EasyEnergy/EnergyZero, ENTSO-E,
// GE-Spot, Tibber/Nordpool custom, Amber, Octopus, PVPC, Omie) rely on the macro's
// auto-detection, which can pick the wrong integration when two are installed.
// Sources that pass their own list (price_data: Zonneplan) ignore it.
const PRICE_SENSOR_ENTITY = 'input_text.house_battery_strategy_dynamic_price_sensor';
const haAll = global.get('homeassistant');
const haSrv = (haAll && typeof haAll === 'object')
    ? Object.values(haAll).find(s => s && s.states && typeof s.states === 'object')
    : undefined;
const haStates = haSrv ? haSrv.states : undefined;
const pinned = haStates && haStates[PRICE_SENSOR_ENTITY] ? String(haStates[PRICE_SENSOR_ENTITY].state || '').trim() : '';

if (msg.dynamic.data_source !== 'None' && msg.dynamic.price_data === undefined && !msg.dynamic.gc_feed) {
    if (/^sensor\.[a-z0-9_]+$/.test(pinned)) {
        msg.dynamic.sensor = pinned;
        log(this, `Price sensor pinned: ${pinned}`);
    } else if (pinned && !['unknown', 'unavailable'].includes(pinned)) {
        log(this, `Ignoring ${PRICE_SENSOR_ENTITY} = '${pinned}': not a sensor entity id`, 'warn');
    }
    if (!msg.dynamic.sensor) {
        node.status({ fill: 'yellow', shape: 'ring', text: `${msg.dynamic.data_source}: sensor auto-detected` });
        log(this, `No price sensor named for ${msg.dynamic.data_source}; the macro auto-detects it. Set ${PRICE_SENSOR_ENTITY} to pin it.`);
    } else if (haStates && !haStates[msg.dynamic.sensor]) {
        node.status({ fill: 'red', shape: 'ring', text: `${msg.dynamic.sensor} not found` });
        log(this, `Price sensor ${msg.dynamic.sensor} does not exist in Home Assistant`, 'warn');
    } else {
        node.status({ fill: 'green', shape: 'dot', text: `${msg.dynamic.data_source}: ${msg.dynamic.sensor}` });
    }
} else {
    node.status({ fill: 'green', shape: 'dot', text: `${msg.dynamic.data_source}` });
}

log(this, "Performing API calls...");

// Output 1: the Cheapest Energy Hours macro. Output 2 (HBC+ v1.2): the Grid Clock feed.
return msg.dynamic.gc_feed ? [null, msg] : [msg, null];

// Init
msg.dynamic = {};
msg.log = [];
return msg;

// final template initialization
msg.dynamic.template_all = "";

// temporary template parts
let template_start = "";
let template_common = [];
let template_all = [];
let template_end = "";

// load the macro
// A data source may inject raw Jinja through msg.dynamic.template_prefix. That is used when
// the source data has to be reshaped before it can be handed to the macro — see the Zonneplan
// case in 'Data source settings'.
const template_lines = [`{% from 'cheapest_energy_hours.jinja' import cheapest_energy_hours %}`];
if (msg.dynamic.template_prefix) {
    template_lines.push(msg.dynamic.template_prefix);
}
template_lines.push(`{{ cheapest_energy_hours(`);
template_start = template_lines.join("\n") + "\n";
template_end = `) | to_json }}`;

// collect arguments | strings
const stringKeys = [
    'sensor',
    'attr_all',
    'value_key',
    'attr_today',
    'attr_tomorrow',
    'time_key',
    'source_settings'
];

stringKeys.forEach(key => {
    if (msg.dynamic[key] !== undefined) {
        template_common.push(`${key}='${msg.dynamic[key]}'`);
    }
});

// collect arguments | boolean, integer
const otherKeys = [
    'datetime_in_data',
    'data_minutes',
    'price_data', // a Jinja variable name, so it must be emitted unquoted
];

otherKeys.forEach(key => {
    if (msg.dynamic[key] !== undefined) {
        template_common.push(`${key}=${msg.dynamic[key]}`);
    }
});

// copy common items
template_all = [...template_common];

// collect all hours | via extra call
template_all.push(`hours="all"`);
template_all.push(`include_tomorrow=true`);
template_all.push(`mode="all"`);

/**
 * Formats an array of strings into a single string:
 * - Each item starts with 4 spaces.
 * - Each item ends with a comma, except the last one.
 * - Items are separated by a newline.
 */
function formatTemplateArray(array) {
    if (!array || array.length === 0) {
        return "";
    }

    const indent = "    "; 

    const formatted_lines = array.map((element, index) => {
        const suffix = (index < array.length - 1) ? "," : "";
        return `${indent}${element}${suffix}`;
    });

    return formatted_lines.join('\n');
}

// generate string templates
const template_all_string = formatTemplateArray(template_all);

// done
msg.dynamic.template_all = `${template_start}${template_all_string}${template_end}`;

return msg;

// HBC+ 2026-11-15 (same as Self-consumption's Trace since 2026-10-13): was a change node with the JSONata expression
//   [strategy.trace, {"flow": target, "flow_settings": advanced_settings, "timestamp": $now()}]
// Same result in plain JavaScript (JSONata is slow and this runs on every tick).
const prev = RED.util.getMessageProperty(msg, 'strategy.trace');
const trace = prev === undefined || prev === null ? [] : (Array.isArray(prev) ? prev.slice() : [prev]);
const entry = { flow: msg.target };
if (msg.advanced_settings !== undefined) entry.flow_settings = msg.advanced_settings;
entry.timestamp = new Date().toISOString();
trace.push(entry);
RED.util.setMessageProperty(msg, 'strategy.trace', trace, true);
return msg;

// HBC+ v1.2 price guard: swap the strategy about to run while prices are below a threshold.
// msg.price_override is built once per tick in 'Strategy selection' (Home Battery Start).
// No override object = no change; Full stop is never changed. Monitor only records 'would'.
{
    const po = msg.price_override;
    const to = po && po.map && msg.target !== 'Full stop' ? po.map[msg.target] : undefined;
    if (to && to !== msg.target) {
