// replies: with the last valid prices (msg.dynamic.stale = true) or with msg.dynamic.no_data.
const log = (global.get('logger') || (() => {}));
const SRC_ENTITY = 'input_select.house_battery_strategy_dynamic_data_source';

const empty = (source, why) => {
    msg.dynamic = {
        data_source: source, no_data: true,
        data_all: { list: [], list_marked: [], average: 0, mark_now: 'No data', start: 'Unknown', datapoints_per_hour: 0, net_spread_avg: 0, gross_spread_avg: 0 }
    };
    node.status({ fill: 'red', shape: 'ring', text: why });
    return [null, msg];
};

msg.dynamic = (msg.dynamic && typeof msg.dynamic === 'object') ? msg.dynamic : {};
let source = msg.dynamic.data_source;

