node.status({ fill: 'blue', shape: 'dot', text: `${zone}/${slug}` });
log(this, `Grid Clock feed: ${zone}/${slug}`);
return msg;

// HBC+ v1.2: Grid Clock feed -> msg.dynamic.data_all in the same shape as the macro path
// after 'Convert price' (ct/kWh), plus data_all.sell. Output 1 -> Cleanup -> Price split ->
// Cache data source (a failed fetch keeps the last valid prices there). Output 2 -> the
// HA event hbc_gridclock_status (sensor.hbc_grid_clock_feed).
// BE: the chosen grid operator's ct/kWh (incl. VAT) is added to the buy price, and to the
// sell price only where sell = buy (net metering), from the supplier index ('gc_index').
const log = (global.get('logger') || (() => {}));
const g = msg.gc || {};
const cache = flow.get('gc_feed_cache') || {};
const nowIso = new Date().toISOString();

const fail = (why) => {
    node.status({ fill: 'red', shape: 'ring', text: why });
    log(this, `Grid Clock feed ${g.zone}/${g.slug}: ${why}`, 'warn');
    msg.dynamic = msg.dynamic || {};
    msg.dynamic.no_data = true;
    msg.dynamic.data_all = { list: [], list_marked: [], average: 0, mark_now: 'No data', start: 'Unknown', datapoints_per_hour: 0, net_spread_avg: 0, gross_spread_avg: 0 };
