    const v = e ? String(e.state || '').trim() : '';
    return ['', 'unknown', 'unavailable'].includes(v) ? '' : v;
};

const MARKET = 'Market price (no supplier)';
const NONE_OP = 'None';
const zone = msg.gc_zone;
if (msg.statusCode !== 200 || !msg.payload || typeof msg.payload !== 'object' || !Array.isArray(msg.payload.providers)) {
    node.status({ fill: 'red', shape: 'ring', text: `${zone}: index ${msg.statusCode || 'no answer'}` });
    log(this, `Grid Clock index ${zone}: ${msg.statusCode || 'no answer'}`, 'warn');
